def getSheetData(url, sheetName, **_extra):
    import json, os, datetime, time, re, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0241000" if __import__("os").path.isdir("./environment_mix/0241000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    spreadsheets = _load("spreadsheets.json")
    sheets = _load("sheets.json")
    snapshots = _load("sheet_data_snapshots.json")
    logs = _load("spreadsheet_access_logs.json")

    TTL_SECONDS = 300  # configured TTL

    def _new_id(prefix):
        seed = f"{prefix}:{now}:{random.random()}".encode("utf-8")
        return prefix + "_" + hashlib.sha256(seed).hexdigest()[:24]

    def _normalize_url(u):
        if not isinstance(u, str) or not u.strip():
            return None
        u = u.strip()
        u = u.split("#", 1)[0]
        u = u.split("?", 1)[0]
        u = u.rstrip("/")
        return u

    def _parse_google_sheet_id(u):
        m = re.search(r"^https?://docs\.google\.com/spreadsheets/d/([a-zA-Z0-9\-_]+)", u)
        if m:
            return m.group(1)
        return None

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _append_log(tool_name, request_url, request_sheet_name, spreadsheet_id, sheet_id, response_status, cache_hit, error_code=None, error_message=None, provider_latency_ms=None):
        log_row = {
            "id": _new_id("log"),
            "tool_name": tool_name,
            "request_url": request_url if isinstance(request_url, str) else "",
            "request_sheet_name": request_sheet_name,
            "spreadsheet_id": spreadsheet_id,
            "sheet_id": sheet_id,
            "response_status": response_status,
            "provider_latency_ms": provider_latency_ms,
            "cache_hit": bool(cache_hit),
            "error_code": error_code,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        }
        logs.append(log_row)
        _save("spreadsheet_access_logs.json", logs)

    # Validate inputs
    if not isinstance(url, str) or not url.strip():
        _append_log("getSheetData", url, sheetName if isinstance(sheetName, str) else None, None, None, "invalid_argument", False, error_code="VALIDATION_ERROR", error_message="url is required")
        return _err("VALIDATION_ERROR", "url is required")
    if not isinstance(sheetName, str) or not sheetName.strip():
        _append_log("getSheetData", url, sheetName if isinstance(sheetName, str) else None, None, None, "invalid_argument", False, error_code="VALIDATION_ERROR", error_message="sheetName is required")
        return _err("VALIDATION_ERROR", "sheetName is required")

    norm = _normalize_url(url)
    if not norm:
        _append_log("getSheetData", url, sheetName, None, None, "invalid_argument", False, error_code="VALIDATION_ERROR", error_message="url is invalid")
        return _err("VALIDATION_ERROR", "url is invalid")

    ext_id = _parse_google_sheet_id(norm)
    if not ext_id:
        _append_log("getSheetData", url, sheetName, None, None, "invalid_argument", False, error_code="VALIDATION_ERROR", error_message="url is not a valid Google Sheets spreadsheet URL")
        return _err("VALIDATION_ERROR", "url is not a valid Google Sheets spreadsheet URL")

    # Resolve spreadsheet
    ss = None
    for r in spreadsheets:
        if r.get("provider") == "google_sheets" and r.get("normalized_url") == norm:
            ss = r
            break
    if ss is None:
        _append_log("getSheetData", url, sheetName, None, None, "not_found", False, error_code="NOT_FOUND", error_message="Spreadsheet not tracked")
        return _err("NOT_FOUND", "Spreadsheet not found.")

    # Spreadsheet status gates
    st = ss.get("status")
    if st in ("restricted", "not_found", "archived", "error"):
        resp_status = "restricted" if st == "restricted" else ("not_found" if st in ("not_found", "archived") else "error")
        _append_log("getSheetData", url, sheetName, ss.get("id"), None, resp_status, False, error_code=ss.get("last_error_code") or st.upper(), error_message=ss.get("last_error_message") or "Spreadsheet not accessible")
        return _err("NOT_FOUND", "Spreadsheet not accessible.", reason=st)

    # Resolve sheet by (spreadsheet_id, name) where status in ('active','hidden')
    sh = None
    for r in sheets:
        if r.get("spreadsheet_id") == ss.get("id") and r.get("name") == sheetName and r.get("status") in ("active", "hidden"):
            sh = r
            break
    if sh is None:
        _append_log("getSheetData", url, sheetName, ss.get("id"), None, "not_found", False, error_code="NOT_FOUND", error_message="Sheet not found")
        return _err("NOT_FOUND", "Sheet not found in spreadsheet.")

    # Find newest fresh snapshot
    fresh_snaps = [s for s in snapshots if s.get("sheet_id") == sh.get("id") and s.get("spreadsheet_id") == ss.get("id") and s.get("status") == "fresh"]
    fresh_snaps.sort(key=lambda r: _parse_dt(r.get("fetched_at")) or datetime.datetime.min, reverse=True)
    newest_fresh = fresh_snaps[0] if fresh_snaps else None

    def _is_within_ttl(snap):
        if not snap:
            return False
        t = _parse_dt(snap.get("fetched_at"))
        if not t:
            return False
        age = (now_dt - t).total_seconds()
        return age <= TTL_SECONDS

    provider_latency_ms = None
    cache_hit = False

    if newest_fresh and _is_within_ttl(newest_fresh):
        cache_hit = True
        _append_log("getSheetData", url, sheetName, ss.get("id"), sh.get("id"), "ok", True, provider_latency_ms=None)
        return {"spreadsheet": dict(ss), "sheet": dict(sh), "snapshot": dict(newest_fresh)}

    # Otherwise "fetch from provider" and create new fresh snapshot
    t0 = time.time()
    low = (norm + " " + sheetName).lower()
    if "quota" in low or "rate" in low:
        provider_latency_ms = max(0, int((time.time() - t0) * 1000))
        _append_log("getSheetData", url, sheetName, ss.get("id"), sh.get("id"), "error", False, error_code="QUOTA_EXCEEDED", error_message="Upstream quota exceeded.", provider_latency_ms=provider_latency_ms)
        return _err("QUOTA_EXCEEDED", "Upstream quota exceeded.")

    # Generate deterministic small table based on sheet id/name
    base = sum(ord(c) for c in (sh.get("id") or "")) + sum(ord(c) for c in sheetName)
    rows = (base % 5) + 3
    cols = (base % 4) + 2
    values = []
    for r in range(rows):
        row = []
        for c in range(cols):
            if r == 0:
                row.append(f"col{c+1}")
            else:
                row.append(f"{sheetName}:{r},{c}")
        values.append(row)

    provider_latency_ms = max(0, int((time.time() - t0) * 1000))

    # Mark older fresh snapshots as stale (legal transition fresh->stale)
    changed = False
    for s in snapshots:
        if s.get("sheet_id") == sh.get("id") and s.get("spreadsheet_id") == ss.get("id") and s.get("status") == "fresh":
            s["status"] = "stale"
            s["updated_at"] = now
            changed = True
    if changed:
        _save("sheet_data_snapshots.json", snapshots)

    # Compute row_count/column_count
    row_count = len(values) if isinstance(values, list) else 0
    col_count = 0
    if isinstance(values, list):
        for rr in values:
            if isinstance(rr, list):
                col_count = max(col_count, len(rr))
            else:
                col_count = max(col_count, 0)

    snap = {
        "id": _new_id("snap"),
        "spreadsheet_id": ss.get("id"),
        "sheet_id": sh.get("id"),
        "range_a1": None,
        "major_dimension": "ROWS",
        "values": values,
        "row_count": row_count,
        "column_count": col_count,
        "etag": None,
        "fetched_at": now,
        "status": "fresh",
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    snapshots.append(snap)
    _save("sheet_data_snapshots.json", snapshots)

    _append_log("getSheetData", url, sheetName, ss.get("id"), sh.get("id"), "ok", False, provider_latency_ms=provider_latency_ms)

    return {"spreadsheet": dict(ss), "sheet": dict(sh), "snapshot": dict(snap)}

def listSpreadsheets(provider=None, status=None, urlContains=None, normalizedUrl=None, pageSize=None, pageToken=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0241000" if __import__("os").path.isdir("./environment_mix/0241000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    spreadsheets = _load("spreadsheets.json")
    logs = _load("spreadsheet_access_logs.json")

    def _append_log(response_status, cache_hit, error_code=None, error_message=None):
        # request_url is required in logs schema; for list tools we store empty string
        log_row = {
            "id": "log_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "tool_name": "getSpreadsheet",  # closest enum; schema restricts tool_name to two values
            "request_url": "",
            "request_sheet_name": None,
            "spreadsheet_id": None,
            "sheet_id": None,
            "response_status": response_status,
            "provider_latency_ms": None,
            "cache_hit": bool(cache_hit),
            "error_code": error_code,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        }
        logs.append(log_row)
        _save("spreadsheet_access_logs.json", logs)

    # Validate filters
    if provider is not None and provider not in ("google_sheets",):
        _append_log("invalid_argument", True, error_code="VALIDATION_ERROR", error_message="Invalid provider")
        return _err("VALIDATION_ERROR", "Invalid provider.")
    if status is not None and status not in ("active", "restricted", "not_found", "error", "archived"):
        _append_log("invalid_argument", True, error_code="VALIDATION_ERROR", error_message="Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status.")
    if urlContains is not None and not isinstance(urlContains, str):
        _append_log("invalid_argument", True, error_code="VALIDATION_ERROR", error_message="urlContains must be a string")
        return _err("VALIDATION_ERROR", "urlContains must be a string.")
    if normalizedUrl is not None and not isinstance(normalizedUrl, str):
        _append_log("invalid_argument", True, error_code="VALIDATION_ERROR", error_message="normalizedUrl must be a string")
        return _err("VALIDATION_ERROR", "normalizedUrl must be a string.")

    if pageSize is None:
        pageSize = 50
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        _append_log("invalid_argument", True, error_code="VALIDATION_ERROR", error_message="pageSize out of range")
        return _err("VALIDATION_ERROR", "pageSize must be between 1 and 200.")

    # Decode pageToken (offset-based)
    offset = 0
    if pageToken is not None:
        if not isinstance(pageToken, str) or not pageToken:
            _append_log("invalid_argument", True, error_code="VALIDATION_ERROR", error_message="pageToken invalid")
            return _err("VALIDATION_ERROR", "pageToken is invalid.")
        try:
            raw = base64.urlsafe_b64decode(pageToken.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                _append_log("invalid_argument", True, error_code="VALIDATION_ERROR", error_message="pageToken malformed")
                return _err("VALIDATION_ERROR", "pageToken is malformed.")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except Exception:
            _append_log("invalid_argument", True, error_code="VALIDATION_ERROR", error_message="pageToken malformed")
            return _err("VALIDATION_ERROR", "pageToken is malformed.")

    # Filter
    rows = spreadsheets
    if provider is not None:
        rows = [r for r in rows if r.get("provider") == provider]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if normalizedUrl is not None:
        rows = [r for r in rows if r.get("normalized_url") == normalizedUrl]
    if urlContains is not None:
        needle = urlContains.lower()
        rows = [r for r in rows if isinstance(r.get("url"), str) and needle in r.get("url").lower()]

    # Order by updated_at desc
    def _key(r):
        v = r.get("updated_at")
        if isinstance(v, str):
            return v
        return ""
    rows.sort(key=_key, reverse=True)

    total = len(rows)
    page = rows[offset:offset + pageSize]
    next_off = offset + len(page)
    has_more = next_off < total
    next_token = None
    if has_more:
        next_token = base64.urlsafe_b64encode(f"offset:{next_off}".encode("utf-8")).decode("utf-8")

    _append_log("ok", True)

    return {
        "spreadsheets": [dict(r) for r in page],
        "total": total,
        "page_size": pageSize,
        "next_page_token": next_token,
        "has_more": has_more
    }

def getSpreadsheetById(id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0241000" if __import__("os").path.isdir("./environment_mix/0241000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    spreadsheets = _load("spreadsheets.json")
    logs = _load("spreadsheet_access_logs.json")

    def _append_log(response_status, spreadsheet_id, error_code=None, error_message=None):
        log_row = {
            "id": "log_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "tool_name": "getSpreadsheet",  # closest enum available in schema
            "request_url": "",
            "request_sheet_name": None,
            "spreadsheet_id": spreadsheet_id,
            "sheet_id": None,
            "response_status": response_status,
            "provider_latency_ms": None,
            "cache_hit": True,
            "error_code": error_code,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        }
        logs.append(log_row)
        _save("spreadsheet_access_logs.json", logs)

    if not isinstance(id, str) or not id.strip():
        _append_log("invalid_argument", None, error_code="VALIDATION_ERROR", error_message="id is required")
        return _err("VALIDATION_ERROR", "id is required")

    row = None
    for r in spreadsheets:
        if r.get("id") == id:
            row = r
            break

    if row is None:
        _append_log("not_found", None, error_code="NOT_FOUND", error_message="Spreadsheet not found")
        return _err("NOT_FOUND", "Spreadsheet not found.")

    _append_log("ok", row.get("id"))
    return {"spreadsheet": dict(row)}

def updateSpreadsheet(id, status=None, title=None, locale=None, timezone=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0241000" if __import__("os").path.isdir("./environment_mix/0241000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    now = _now()

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ["active", "restricted", "not_found", "error", "archived"]:
            return _err("VALIDATION_ERROR", "status must be one of: active, restricted, not_found, error, archived")
    for k, v in [("title", title), ("locale", locale), ("timezone", timezone)]:
        if v is not None and not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{k} must be a string")

    spreadsheets = _load("spreadsheets.json")
    sheets = _load("sheets.json")

    idx = None
    for i, r in enumerate(spreadsheets):
        if r.get("id") == id:
            idx = i
            break

    # Prepare access log (must append on every call)
    logs = _load("spreadsheet_access_logs.json")
    log_row = {
        "id": _new_id("sal"),
        "tool_name": "getSpreadsheet",  # closest enumerated tool_name available in schema for mutation calls
        "request_url": id,              # schema expects url; store id for traceability
        "request_sheet_name": None,
        "spreadsheet_id": id if idx is not None else None,
        "sheet_id": None,
        "response_status": "ok",
        "provider_latency_ms": None,
        "cache_hit": False,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    if idx is None:
        log_row["response_status"] = "not_found"
        logs.append(log_row)
        _save("spreadsheet_access_logs.json", logs)
        return _err("NOT_FOUND", "Spreadsheet not found", id=id)

    row = spreadsheets[idx]

    # Enforce lifecycle transitions
    transitions = {
        "active": ["restricted", "not_found", "error", "archived"],
        "restricted": ["active", "error", "archived"],
        "not_found": ["active", "archived"],
        "error": ["active", "restricted", "not_found", "archived"],
        "archived": [],
    }

    # Apply updates
    changed = False
    if status is not None and status != row.get("status"):
        cur = row.get("status")
        if cur not in transitions:
            log_row["response_status"] = "error"
            log_row["error_code"] = "DATA_INTEGRITY"
            log_row["error_message"] = f"Unknown current status '{cur}'"
            logs.append(log_row)
            _save("spreadsheet_access_logs.json", logs)
            return _err("CONFLICT", "Spreadsheet row has invalid current status", current_status=cur)
        if status not in transitions[cur]:
            log_row["response_status"] = "invalid_argument"
            log_row["error_code"] = "INVALID_TRANSITION"
            log_row["error_message"] = f"Cannot transition status from {cur} to {status}"
            logs.append(log_row)
            _save("spreadsheet_access_logs.json", logs)
            return _err("INVALID_TRANSITION", "Invalid status transition", from_status=cur, to_status=status)
        row["status"] = status
        changed = True

    if title is not None and title != row.get("title"):
        row["title"] = title
        changed = True
    if locale is not None and locale != row.get("locale"):
        row["locale"] = locale
        changed = True
    if timezone is not None and timezone != row.get("timezone"):
        row["timezone"] = timezone
        changed = True

    if not changed:
        # Still a successful mutation request but no effect should not be reported as success in this system.
        # However, the contract says: "No success without effect" for mutations that matched no row.
        # Here it matched a row; it's an idempotent no-op update, which should return the row.
        pass

    row["updated_at"] = now
    spreadsheets[idx] = row
    _save("spreadsheets.json", spreadsheets)

    # Return derived view (spreadsheet plus non-deleted sheets), consistent with getSpreadsheet derivation rule.
    derived_sheets = [
        s for s in sheets
        if s.get("spreadsheet_id") == id and s.get("status") != "deleted"
    ]

    # Log
    log_row["response_status"] = "ok"
    log_row["spreadsheet_id"] = id
    log_row["provider_latency_ms"] = int((time.time() - t0) * 1000)
    logs.append(log_row)
    _save("spreadsheet_access_logs.json", logs)

    return {
        "spreadsheet": row,
        "sheets": derived_sheets,
    }

def listSheetDataSnapshots(url, sheetName, status=None, rangeA1=None, pageSize=None, pageToken=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0241000" if __import__("os").path.isdir("./environment_mix/0241000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _norm_url(u):
        # Canonicalize: trim, remove fragment, drop query, remove trailing slash
        u = u.strip()
        if not u:
            return ""
        u = u.split("#", 1)[0]
        u = u.split("?", 1)[0]
        if u.endswith("/"):
            u = u[:-1]
        return u

    def _log(tool, req_url, req_sheet, spreadsheet_id, sheet_id, resp_status, cache_hit, err_code=None, err_msg=None, provider_ms=None):
        logs = _load("spreadsheet_access_logs.json")
        now = _now()
        row = {
            "id": _new_id("sal"),
            "tool_name": tool,
            "request_url": req_url,
            "request_sheet_name": req_sheet,
            "spreadsheet_id": spreadsheet_id,
            "sheet_id": sheet_id,
            "response_status": resp_status,
            "provider_latency_ms": provider_ms,
            "cache_hit": bool(cache_hit),
            "error_code": err_code,
            "error_message": err_msg,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("spreadsheet_access_logs.json", logs)

    t0 = time.time()

    # Validate
    if not isinstance(url, str) or not url.strip():
        _log("getSheetData", url if isinstance(url, str) else "", sheetName if isinstance(sheetName, str) else None,
             None, None, "invalid_argument", False, "INVALID_ARGUMENT", "url must be a non-empty string")
        return _err("VALIDATION_ERROR", "url must be a non-empty string")
    if not isinstance(sheetName, str) or not sheetName.strip():
        _log("getSheetData", url, sheetName if isinstance(sheetName, str) else None,
             None, None, "invalid_argument", False, "INVALID_ARGUMENT", "sheetName must be a non-empty string")
        return _err("VALIDATION_ERROR", "sheetName must be a non-empty string")
    if status is not None:
        if not isinstance(status, str) or status not in ["fresh", "stale", "error"]:
            _log("getSheetData", url, sheetName, None, None, "invalid_argument", False, "INVALID_ARGUMENT", "Invalid status filter")
            return _err("VALIDATION_ERROR", "status must be one of: fresh, stale, error")
    if rangeA1 is not None and not isinstance(rangeA1, str):
        _log("getSheetData", url, sheetName, None, None, "invalid_argument", False, "INVALID_ARGUMENT", "rangeA1 must be a string")
        return _err("VALIDATION_ERROR", "rangeA1 must be a string")
    if pageSize is None:
        pageSize = 20
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 100:
        _log("getSheetData", url, sheetName, None, None, "invalid_argument", False, "INVALID_ARGUMENT", "pageSize out of range")
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 100")
    if pageToken is not None and not isinstance(pageToken, str):
        _log("getSheetData", url, sheetName, None, None, "invalid_argument", False, "INVALID_ARGUMENT", "pageToken must be a string")
        return _err("VALIDATION_ERROR", "pageToken must be a string")

    # Quota enforcement: max 1000 list calls per rolling 24h
    logs = _load("spreadsheet_access_logs.json")
    now_dt = datetime.datetime.utcnow()
    cutoff = now_dt - datetime.timedelta(hours=24)
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    recent = 0
    for lr in logs:
        if lr.get("tool_name") == "getSheetData":
            dt = _parse_dt(lr.get("created_at"))
            if dt is not None and dt >= cutoff:
                recent += 1
    if recent >= 1000:
        _log("getSheetData", url, sheetName, None, None, "error", False, "QUOTA_EXCEEDED", "Daily quota exceeded")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for sheet snapshot listing", limit=1000, window_hours=24)

    spreadsheets = _load("spreadsheets.json")
    sheets = _load("sheets.json")
    snaps = _load("sheet_data_snapshots.json")

    nurl = _norm_url(url)
    if not nurl:
        _log("getSheetData", url, sheetName, None, None, "invalid_argument", False, "INVALID_ARGUMENT", "Could not normalize url")
        return _err("VALIDATION_ERROR", "Invalid url")

    spreadsheet = None
    for sp in spreadsheets:
        if sp.get("provider") == "google_sheets" and sp.get("normalized_url") == nurl:
            spreadsheet = sp
            break

    if spreadsheet is None:
        _log("getSheetData", url, sheetName, None, None, "not_found", False, "NOT_FOUND", "Spreadsheet not found")
        return _err("NOT_FOUND", "Spreadsheet not found for url", url=url)

    sheet = None
    for sh in sheets:
        if sh.get("spreadsheet_id") == spreadsheet.get("id") and sh.get("name") == sheetName:
            sheet = sh
            break

    if sheet is None:
        _log("getSheetData", url, sheetName, spreadsheet.get("id"), None, "not_found", False, "NOT_FOUND", "Sheet not found")
        return _err("NOT_FOUND", "Sheet not found for spreadsheet", sheetName=sheetName)

    # Filter snapshots
    filtered = []
    for s in snaps:
        if s.get("spreadsheet_id") != spreadsheet.get("id"):
            continue
        if s.get("sheet_id") != sheet.get("id"):
            continue
        if status is not None and s.get("status") != status:
            continue
        if rangeA1 is not None and s.get("range_a1") != rangeA1:
            continue
        filtered.append(s)

    # Sort newest first by fetched_at then created_at
    def _key(r):
        return (r.get("fetched_at") or "", r.get("created_at") or "")
    filtered.sort(key=_key, reverse=True)

    # Pagination token: base64 of JSON {"offset": int}
    offset = 0
    if pageToken:
        try:
            raw = base64.urlsafe_b64decode(pageToken.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                offset = obj["offset"]
            else:
                _log("getSheetData", url, sheetName, spreadsheet.get("id"), sheet.get("id"),
                     "invalid_argument", False, "INVALID_ARGUMENT", "Invalid pageToken")
                return _err("VALIDATION_ERROR", "Invalid pageToken")
        except Exception:
            _log("getSheetData", url, sheetName, spreadsheet.get("id"), sheet.get("id"),
                 "invalid_argument", False, "INVALID_ARGUMENT", "Invalid pageToken encoding")
            return _err("VALIDATION_ERROR", "Invalid pageToken")

    total = len(filtered)
    page = filtered[offset:offset + pageSize]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        tok = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8")
        next_cursor = tok

    # Log (served from cache history -> cache_hit True)
    _log(
        "getSheetData",
        url,
        sheetName,
        spreadsheet.get("id"),
        sheet.get("id"),
        "ok",
        True,
        provider_ms=int((time.time() - t0) * 1000),
    )

    return {
        "snapshots": page,
        "spreadsheet_id": spreadsheet.get("id"),
        "sheet_id": sheet.get("id"),
        "total": total,
        "page_size": pageSize,
        "has_more": has_more,
        "next_page_token": next_cursor,
    }

def updateSheet(id, status=None, name=None, index=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0241000" if __import__("os").path.isdir("./environment_mix/0241000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _coerce_rows(obj):
        if isinstance(obj, list):
            return obj, None
        if isinstance(obj, dict):
            for k in ("rows", "data", "items"):
                if isinstance(obj.get(k), list):
                    return obj[k], (obj, k)
            return [], (obj, "rows")
        return [], None

    def _persist(filename, rows, envinfo):
        if envinfo is None:
            _save(filename, rows)
        else:
            env, key = envinfo
            if not isinstance(env, dict):
                _save(filename, rows)
            else:
                env[key] = rows
                _save(filename, env)

    # ---- validate inputs ----
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    allowed_status = {"active", "hidden", "error", "deleted"}
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string", field="status")
        if status not in allowed_status:
            return _err("VALIDATION_ERROR", "status must be one of: active, hidden, error, deleted", field="status")

    if name is not None:
        if not isinstance(name, str):
            return _err("VALIDATION_ERROR", "name must be a string", field="name")
        if not name.strip():
            return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")

    if index is not None:
        if not isinstance(index, int):
            return _err("VALIDATION_ERROR", "index must be an integer", field="index")
        if index < 0:
            return _err("VALIDATION_ERROR", "index must be >= 0", field="index")

    if status is None and name is None and index is None:
        return _err("VALIDATION_ERROR", "At least one mutable field must be provided: status, name, or index")

    # ---- load sheets ----
    raw = _load("sheets.json")
    sheets, envinfo = _coerce_rows(raw)

    # find target sheet by its own id (NOT spreadsheet id)
    target_idx = None
    target = None
    for i, r in enumerate(sheets):
        if isinstance(r, dict) and r.get("id") == id:
            target_idx = i
            target = r
            break
    if target is None:
        return _err("NOT_FOUND", "Sheet not found", id=id)

    # validate FK integrity (sheet must reference an existing spreadsheet)
    ss_raw = _load("spreadsheets.json")
    spreadsheets, _ = _coerce_rows(ss_raw)
    spreadsheet_id = target.get("spreadsheet_id")
    if not isinstance(spreadsheet_id, str) or not spreadsheet_id:
        return _err("CONFLICT", "Sheet row is missing spreadsheet_id; foreign key integrity violation", id=id)
    parent_exists = any(isinstance(s, dict) and s.get("id") == spreadsheet_id for s in spreadsheets)
    if not parent_exists:
        return _err("CONFLICT", "Parent spreadsheet does not exist; foreign key integrity violation", id=id, spreadsheet_id=spreadsheet_id)

    now = _now_iso()

    # ---- enforce lifecycle transitions ----
    transitions = {
        "active": {"hidden", "deleted", "error"},
        "hidden": {"active", "deleted", "error"},
        "error": {"active", "hidden", "deleted"},
        "deleted": set(),
    }
    current_status = target.get("status")
    if not isinstance(current_status, str) or current_status not in transitions:
        return _err("CONFLICT", "Sheet row has invalid current status", id=id, status=current_status)

    if status is not None:
        if status != current_status:
            allowed = transitions.get(current_status, set())
            if status not in allowed:
                return _err(
                    "INVALID_TRANSITION",
                    "Invalid status transition",
                    id=id,
                    from_status=current_status,
                    to_status=status,
                    allowed_transitions=sorted(list(allowed)),
                )

    # ---- enforce unique(spreadsheet_id, name) ----
    if name is not None:
        new_name = name.strip()
        # if unchanged (ignoring surrounding whitespace), treat as idempotent rename
        existing_name = target.get("name")
        if isinstance(existing_name, str) and existing_name == new_name:
            pass
        else:
            for r in sheets:
                if not isinstance(r, dict):
                    continue
                if r.get("id") == id:
                    continue
                if r.get("spreadsheet_id") == spreadsheet_id and r.get("name") == new_name:
                    return _err(
                        "CONFLICT",
                        "Sheet name must be unique within the parent spreadsheet (unique(spreadsheet_id, name))",
                        spreadsheet_id=spreadsheet_id,
                        name=new_name,
                        conflicting_sheet_id=r.get("id"),
                    )

    # ---- apply mutations ----
    changed = False

    if status is not None and status != current_status:
        target["status"] = status
        changed = True

    if name is not None:
        new_name = name.strip()
        if target.get("name") != new_name:
            target["name"] = new_name
            changed = True

    if index is not None:
        if target.get("index") != index:
            target["index"] = index
            changed = True

    if not changed:
        # idempotent: return current row, but still a "real" update isn't required
        # (this tool is not specified to require a write on no-op).
        return {"sheet": target}

    target["updated_at"] = now
    if not target.get("created_at"):
        target["created_at"] = now

    sheets[target_idx] = target
    _persist("sheets.json", sheets, envinfo)

    return {"sheet": target}
